/// What a themed subtree asks for. `None` means "inherit".
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct ScopeRequest {
    /// The `mode` this scope asks for.
    pub mode: Option<Mode>,
    /// The `accent` this scope asks for.
    pub accent: Option<Accent>,
    /// The `saturation` this scope asks for.
    pub saturation: Option<Saturation>,
    /// The `palette` this scope asks for.
    pub palette: Option<Palette>,
    /// The `font` this scope asks for.
    pub font: Option<Font>,
    /// The `glass` this scope asks for.
    pub glass: Option<Glass>,
    /// The `radius` this scope asks for.
    pub radius: Option<Radius>,
}

/// What the surrounding page or scope already resolved to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Resolved {
    /// The inherited `mode`.
    pub mode: Mode,
    /// The inherited `accent`.
    pub accent: Accent,
    /// The inherited `saturation`.
    pub saturation: Saturation,
    /// The inherited `palette`.
    pub palette: Palette,
    /// The inherited `font`.
    pub font: Font,
    /// The inherited `glass`.
    pub glass: Glass,
    /// The inherited `radius`.
    pub radius: Radius,
}

impl Default for Resolved {
    fn default() -> Self {
        Self {
            mode: Mode::DEFAULT,
            accent: Accent::DEFAULT,
            saturation: Saturation::DEFAULT,
            palette: Palette::DEFAULT,
            font: Font::DEFAULT,
            glass: Glass::DEFAULT,
            radius: Radius::DEFAULT,
        }
    }
}

impl ScopeRequest {
    /// Resolves this request against what it inherits.
    #[must_use]
    pub fn resolve(self, inherited: Resolved) -> Resolved {
        Resolved {
            mode: match self.mode {
                Some(v) => v,
                None => inherited.mode,
            },
            accent: match self.accent {
                Some(v) => v,
                None => inherited.accent,
            },
            saturation: match self.saturation {
                Some(v) => v,
                None => inherited.saturation,
            },
            palette: match self.palette {
                Some(v) => v,
                None => inherited.palette,
            },
            font: match self.font {
                Some(v) => v,
                None => inherited.font,
            },
            glass: match self.glass {
                Some(v) => v,
                None => inherited.glass,
            },
            radius: match self.radius {
                Some(v) => v,
                None => inherited.radius,
            },
        }
    }

    /// Whether this scope changes anything at all.
    ///
    /// A scope that matches its surroundings must emit no attributes: the
    /// semantic contract is 1,767 declarations, and re-resolving them for a
    /// subtree that wanted the page's own theme is pure cost.
    #[must_use]
    pub fn is_noop(self, inherited: Resolved) -> bool {
        self.resolve(inherited) == inherited
    }
}

/// Every attribute a scope element must carry, as `(name, value)`.
///
/// # All of them go on ONE element
///
/// The colour system's forced-mode selector is **compound and
/// same-element**:
///
/// ```css
/// [data-palette="blue-vivid"][data-theme="dark"] { … }
/// ```
///
/// Split the two across a wrapper and a child and that selector matches
/// nothing — the child falls through to the *default* palette's unanchored
/// `[data-theme="dark"]` and silently paints the wrong palette.
///
/// # Mode and palette travel together
///
/// For the same reason, stamping a mode without a palette is never right:
/// the compound needs both halves. So the palette is always emitted when
/// the scope is not a no-op, even when it equals the inherited one.
#[must_use]
pub fn scope_attributes(
    request: ScopeRequest,
    inherited: Resolved,
) -> ::core::option::Option<ScopeAttributes> {
    if request.is_noop(inherited) {
        return ::core::option::Option::None;
    }
    let r = request.resolve(inherited);
    ::core::option::Option::Some(ScopeAttributes {
        scope: SCOPE_ATTRIBUTE,
        palette: r.palette.as_str(),
        // `system` stamps nothing: the cascade resolves it, and an
        // attribute no stylesheet understands would be worse than none.
        mode: if r.mode.is_omitted() {
            ::core::option::Option::None
        } else {
            ::core::option::Option::Some(r.mode.as_str())
        },
        font: r.font.as_str(),
        glass: r.glass.as_str(),
        radius: r.radius.as_str(),
    })
}

/// The attributes, ready to be stamped on one element.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ScopeAttributes {
    /// The marker that makes the semantic contract resolve here.
    pub scope: &'static str,
    /// `data-palette`.
    pub palette: &'static str,
    /// `data-theme`, or `None` when the scope follows the system.
    pub mode: ::core::option::Option<&'static str>,
    /// `data-noctua-font`.
    pub font: &'static str,
    /// `data-noctua-glass`.
    pub glass: &'static str,
    /// `data-noctua-radius`.
    pub radius: &'static str,
}
